commit_message_beads.definition:
{"_type":"step","allow_symlinks":false,"batch":false,"check":"awk '
  /^# ------------------------ >8 ------------------------/ { exit }
  /^diff --git / { exit }
  /^#/ { next }
  /^(Refs?|Tasks?|Issues?):/ {
    printf "use the canonical Beads: footer instead of: %s\n", $0 > "/dev/stderr"
    failed = 1
  }
  /^Beads:/ {
    beads += 1
    if ($0 !~ /^Beads: [a-z][a-z0-9-]*-[a-z0-9][a-z0-9.-]*(, [a-z][a-z0-9-]*-[a-z0-9][a-z0-9.-]*)*$/) {
      printf "invalid Beads footer: %s\n", $0 > "/dev/stderr"
      failed = 1
    }
  }
  NF { last = $0 }
  END {
    if (beads > 1) {
      print "commit message must contain at most one Beads: footer" > "/dev/stderr"
      failed = 1
    }
    if (beads == 1 && last !~ /^Beads:/) {
      print "Beads: must be the final nonblank line" > "/dev/stderr"
      failed = 1
    }
    exit failed
  }
' {{commit_msg_file}}","check_first":true,"depends":[],"env":{},"exclude":[],"exclusive":false,"hide":false,"interactive":false,"output_summary":"stderr","required":[],"stomp":false}

commit_message_length.definition:
{"_type":"step","allow_symlinks":false,"batch":false,"check":"awk '
  /^# ------------------------ >8 ------------------------/ { exit }
  /^diff --git / { exit }
  /^#/ { next }
  {
    line += 1
    limit = line == 1 ? 72 : 100
    if (length($0) > limit) {
      printf "commit message line %d is %d characters; maximum is %d\n", line, length($0), limit > "/dev/stderr"
      failed = 1
    }
  }
  END { exit failed }
' {{commit_msg_file}}","check_first":true,"depends":[],"env":{},"exclude":[],"exclusive":false,"hide":false,"interactive":false,"output_summary":"stderr","required":[],"stomp":false}

commit_message_scope.definition:
{"_type":"step","allow_symlinks":false,"batch":false,"check":"awk '
  /^# ------------------------ >8 ------------------------/ { exit }
  /^diff --git / { exit }
  /^#/ { next }
  NF {
    if ($0 ~ /^(feat|fix|perf|refactor)!?: /) {
      print "changelog-visible commit subject must use type(scope): summary" > "/dev/stderr"
      exit 1
    }
    exit 0
  }
' {{commit_msg_file}}","check_first":true,"depends":[],"env":{},"exclude":[],"exclusive":false,"hide":false,"interactive":false,"output_summary":"stderr","required":[],"stomp":false}

harper_commit_message.definition:
{"_type":"step","allow_symlinks":false,"batch":false,"check":"output=$(mktemp)
trap 'rm -f "$output"' EXIT
awk '
  /^# ------------------------ >8 ------------------------/ { exit }
  /^diff --git / { exit }
  /^#/ { next }
  /^Beads: [a-z][a-z0-9-]*-[a-z0-9][a-z0-9.-]*(, [a-z][a-z0-9-]*-[a-z0-9][a-z0-9.-]*)*$/ { next }
  {
    line = $0
    if (!seen_subject && NF) {
      seen_subject = 1
      if (line ~ /^release: v[0-9]+\.[0-9]+\.[0-9]+$/) { next }
      sub(/^[a-z]+(\([^)]+\))?!?: /, "", line)
    }
    print line
  }
' {{commit_msg_file}} | harper-cli lint --quiet --no-color --user-dict-path .config/harper-dictionary.txt 2>"$output"
status=$?
awk '!/^Note: Using user dictionary at /' "$output" >&2
exit "$status"","check_first":true,"depends":[],"env":{},"exclude":[],"exclusive":false,"hide":false,"interactive":false,"output_summary":"stderr","required":[],"stomp":false}
